def _native_task_name(event: Mapping[str, object], session: str, child: str) -> str | None:
    """Correlate native starts that omit tool IDs using their session metadata.

    Read only the bounded first session_meta row, not child output. Missing,
    foreign or ambiguous metadata cannot authorize a post-recovery binding.
    """
    reference = event.get('agent_transcript_path', event.get('transcript_path'))
    if not isinstance(reference, str) or not Path(reference).is_absolute():
        return None
    try:
        with Path(reference).open(encoding='utf-8') as handle:
            line = handle.readline(1024 * 1024 + 1)
        if len(line) > 1024 * 1024:
            return None
        row = json.loads(line)
        payload = row['payload']
        spawn = payload['source']['subagent']['thread_spawn']
        path = spawn['agent_path']
        if (row['type'] != 'session_meta' or payload['id'] != child
                or spawn['parent_thread_id'] != session or not isinstance(path, str)
                or not path.startswith('/') or not path.rsplit('/', 1)[-1]
                or payload.get('agent_path', path) != path):
            return None
        return path.rsplit('/', 1)[-1]
    except (OSError, UnicodeError, ValueError, KeyError, TypeError):
        return None


def _runtime_context(record: Mapping[str, object], event: Mapping[str, object]) -> dict[str, object]:
    """Observe the bound child's exact turn, never infer effort from a request."""
    child = record["child"]
    reference = child.get("transcript_ref")
    turn = event.get("turn_id")
    result = {"state": "UNVERIFIED", "turn_id": turn, "transcript_ref": reference}
    if not reference or not turn:
        return result
    path = Path(reference)
    supplied = event.get("agent_transcript_path")
    if supplied and Path(supplied).resolve() != path.resolve():
        return {**result, "state": "MISMATCH", "reason": "CHILD_TRANSCRIPT_MISMATCH"}
    try:
        raw = path.read_bytes()
        entries = [json.loads(line) for line in raw.splitlines() if line.strip()]
    except (OSError, ValueError):
        return result
    sessions = [e.get("payload", {}).get("id") for e in entries if e.get("type") == "session_meta"]
    contexts = [e["payload"] for e in entries if e.get("type") == "turn_context"
                and e.get("payload", {}).get("turn_id") == turn]
    if not sessions or not contexts:
        return result
    if any(session != child["child_id"] for session in sessions):
        return {**result, "state": "MISMATCH", "reason": "CHILD_TRANSCRIPT_ID_MISMATCH"}
    selected = contexts[-1]
    observed = {k: selected.get(k) for k in ("model", "effort", "cwd", "sandbox_policy")}
    result.update(observed=observed, transcript_sha256=sha256(raw).hexdigest())
    if any(not observed.get(k) for k in ("model", "effort", "cwd")):
        return result
    expected = record["profile"]
    if (observed["model"] != expected["model"] or observed["effort"] != expected["effort"]
            or str(Path(observed["cwd"]).resolve()) != record["identity"]["worktree_root"]):
        return {**result, "state": "MISMATCH", "reason": "CHILD_RUNTIME_PROFILE_MISMATCH"}
    sandbox = _sandbox(observed['sandbox_policy'])
    expected_sandbox = _sandbox(expected.get('sandbox_policy', expected.get('sandbox_mode')))
    if sandbox is None or expected_sandbox is None:
        return {**result, 'reason': 'CHILD_SANDBOX_UNVERIFIED'}
    if sandbox != expected_sandbox:
        return {**result, 'state': 'MISMATCH', 'reason': 'CHILD_SANDBOX_MISMATCH'}
    return {**result, "state": "MATCH"}


class LifecycleStore:
    """A Host-owned state directory supplied explicitly by the coordinator."""
    def bind_child(self, *, session_id: str, child_id: str, event: Mapping[str, object] | None = None) -> dict[str, object]:
        session, child = _text(session_id, "session_id"), _text(child_id, "child_id")
        observed_name = _native_task_name(event, session, child) if event else None
        if event is not None:
            event = dict(event)
        with self._locked() as state:
            candidates = [r for r in self._launches(state).values() if r.get("session_id") == session and r.get("claim") is not None and r.get("child") is None and r.get("terminal_resolution") is None]
            prior = [r for r in self._launches(state).values() if isinstance(r.get("child"), dict) and r["child"].get("child_id") == child]
            recovered = any(r.get('session_id') == session and r.get('terminal_resolution') is not None
                            for r in self._launches(state).values())
            if recovered and event is not None and observed_name is not None:
                if event.get('task_name', observed_name) != observed_name:
                    raise _fail('CHILD_BINDING_AMBIGUOUS', 'Native task path conflicts with the supplied task name.')
                if not any(event.get(k) for k in ('launch_id', 'tool_use_id')):
                    event['task_name'] = observed_name
            def correlated(record):
                if event is None:
                    return True
                return all(event.get(key) is None or event[key] == expected for key, expected in (
                    ('launch_id', record['launch_id']),
                    ('tool_use_id', record['claim'].get('tool_use_id')),
                    ('task_name', record.get('task_name'))))
            if (not prior and recovered
                    and not (event and any(event.get(k) for k in ('launch_id', 'tool_use_id', 'task_name')))):
                raise _fail('CHILD_BINDING_AMBIGUOUS', 'A delayed child event after recovery requires explicit launch correlation.')
            if (not prior and event and event.get('task_name')
                    and not any(event.get(k) for k in ('launch_id', 'tool_use_id'))
                    and any(r.get('session_id') == session and r.get('terminal_resolution')
                            and r.get('task_name') == event['task_name']
                            for r in self._launches(state).values())):
                raise _fail('CHILD_BINDING_AMBIGUOUS', 'A recovered task name cannot correlate a later child by itself.')
            candidates = [r for r in candidates if correlated(r)]
            if prior:
                if len(prior) == 1 and prior[0].get("session_id") == session and correlated(prior[0]):
                    if event is not None:
                        self._validate_event_identity(prior[0], event, require_cwd=True)
                    return deepcopy(prior[0])
                raise _fail("CHILD_ALREADY_BOUND", "Child is bound to another launch.")
            if len(candidates) != 1: raise _fail("CHILD_BINDING_AMBIGUOUS", "Exactly one claimed unbound launch is required.", candidates=len(candidates))
            record = candidates[0]
            if event is not None:
                self._validate_event_identity(record, event, require_cwd=True)
                observed = _observed_profile(event.get("profile", event))
                expected = record["profile"]
                if observed["model"] != expected["model"] or (observed["effort"] != "UNVERIFIED" and observed["effort"] != expected["effort"]):
                    raise _fail("PROFILE_MISMATCH", "Observed child profile differs from registered profile.")
            else:
                observed = {"model": "UNVERIFIED", "model_reasoning_effort": "UNVERIFIED", "effort": "UNVERIFIED"}
            record["child"] = {"child_id": child, "runtime_profile": observed,
                "transcript_ref": event.get("transcript_path") if event else None}
            return dict(record)

    def get_child(self, session_id: str, child_id: str) -> dict[str, object] | None:
        session, child = _text(session_id, "session_id"), _text(child_id, "child_id")
        with self._locked(read_only=True) as state:
            matches = []
            for record in self._launches(state).values():
                bound = record.get('child')
                if record.get('session_id') != session or not isinstance(bound, dict): continue
                if bound.get('child_id') == child or record.get('task_name') in {child, child.rsplit('/', 1)[-1]}:
                    matches.append(record)
            if len(matches) > 1:
                raise _fail('CHILD_BINDING_AMBIGUOUS', 'Child target must resolve to one registered launch.')
            return deepcopy(matches[0]) if matches else None

    def _validate_event_identity(self, record: Mapping[str, object], event: Mapping[str, object], *, require_cwd: bool) -> None:
        if not isinstance(event, Mapping): raise _fail("CHILD_EVENT_INVALID", "Child event must be a mapping.")
        identity = record["identity"]
        if not isinstance(identity, Mapping): raise _fail("LIFECYCLE_STATE_INVALID", "Stored identity is invalid.")
        cwd = event.get("cwd")
        if require_cwd and not isinstance(cwd, str): raise _fail("CHILD_CWD_MISSING", "Child event must report actual cwd.")
        if cwd is not None and str(_absolute(cwd, "event.cwd")) != identity["worktree_root"]:
            raise _fail("CHILD_CWD_MISMATCH", "Child event cwd differs from bound worktree.")
        for key in ("repo_root", "repo_id", "worktree_id", "worktree_root", "head_commit", "run_id", "task_id", "session_id"):
            expected = identity.get(key) if key in identity else record.get(key)
            provided = event.get(key)
            if provided is not None and provided != expected:
                raise _fail("CHILD_IDENTITY_MISMATCH", f"Child event {key} differs from registered identity.")
        actual = _identity(Path(identity["repo_root"]), Path(identity["worktree_root"]))
        if actual != dict(identity): raise _fail("CHILD_IDENTITY_CHANGED", "Bound Git/worktree identity changed before child exit.")

