def patch_paths(tool, input_):
    if tool not in {'apply_patch','functions.apply_patch','exec','functions.exec'}:return set()
    text=(input_.get('command') if tool in {'apply_patch','functions.apply_patch'} else None) or input_.get('patch') or input_.get('input') or input_.get('code') or input_.get('source') or ''
    if not isinstance(text,str):return set()
    # Also see literal patches inside functions.exec. Dynamic shell writes are
    # explicitly outside this bounded recognizer.
    return set(re.findall(r'\*\*\* (?:Add File|Update File|Delete File|Move to): ([^\n\\]+)',text))


def check_edit(event, state, root, tool, input_):
    if state.get('is_child') or not state.get('author_route_turn'):return None
    paths=patch_paths(tool,input_)
    if not paths:return None
    repo=Path(event.get('cwd','')).resolve();relative=set()
    for path in paths:
        try:relative.add(str(Path(path).resolve().relative_to(repo)) if Path(path).is_absolute() else path)
        except ValueError:return 'AUTHOR_ROUTE_OUTSIDE_REPO'
    covered=set()
    for path in (Path(root)/'author-routes').glob('*.json'):
        try:
            row=json.loads(path.read_text())
            assessment=row.get('candidate_assessment')
            pending_native=(row.get('provider')=='CODEX_SUBAGENT_PENDING' or
                            isinstance(assessment,dict) and assessment.get('route')=='CODEX_SUBAGENT')
            if (row.get('session')==event['session_id'] and row.get('turn')==state['author_route_turn']
                    and row.get('repo')==str(repo) and not pending_native):
                covered.update(row['paths'])
        except (OSError,ValueError,KeyError,TypeError):continue
    if relative<=covered:return None
    return 'AUTHOR_ROUTE_REQUIRED: Before this parent patch, run the supplied author-route command for these exact paths with a useful local candidate receipt or a concrete local exclusion: '+', '.join(sorted(relative-covered))


