    def get_child(self, session_id: str, child_id: str) -> dict[str, object] | None:
        session, child = _text(session_id, "session_id"), _text(child_id, "child_id")
        with self._locked(read_only=True) as state:
            matches = []
            for record in self._launches(state).values():
                bound = record.get('child')
                if record.get('session_id') != session or not isinstance(bound, dict): continue
                if bound.get('child_id') == child or record.get('task_name') in {child, child.rsplit('/', 1)[-1]}:
                    matches.append(record)
            if len(matches) > 1:
                raise _fail('CHILD_BINDING_AMBIGUOUS', 'Child target must resolve to one registered launch.')
            return deepcopy(matches[0]) if matches else None

    def _validate_event_identity(self, record: Mapping[str, object], event: Mapping[str, object], *, require_cwd: bool) -> None:
        if not isinstance(event, Mapping): raise _fail("CHILD_EVENT_INVALID", "Child event must be a mapping.")
        identity = record["identity"]
        if not isinstance(identity, Mapping): raise _fail("LIFECYCLE_STATE_INVALID", "Stored identity is invalid.")
        cwd = event.get("cwd")
        if require_cwd and not isinstance(cwd, str): raise _fail("CHILD_CWD_MISSING", "Child event must report actual cwd.")
        if cwd is not None and str(_absolute(cwd, "event.cwd")) != identity["worktree_root"]:
            raise _fail("CHILD_CWD_MISMATCH", "Child event cwd differs from bound worktree.")
        for key in ("repo_root", "repo_id", "worktree_id", "worktree_root", "head_commit", "run_id", "task_id", "session_id"):
            expected = identity.get(key) if key in identity else record.get(key)
            provided = event.get(key)
            if provided is not None and provided != expected:
                raise _fail("CHILD_IDENTITY_MISMATCH", f"Child event {key} differs from registered identity.")
        actual = _identity(Path(identity["repo_root"]), Path(identity["worktree_root"]))
        if actual != dict(identity): raise _fail("CHILD_IDENTITY_CHANGED", "Bound Git/worktree identity changed before child exit.")

def record(*, root, session, turn, repo, task, reason, detail, paths, evidence=None, assessment=None):
    repo=Path(repo).resolve()
    if reason not in REASONS or not isinstance(detail,str) or len(detail.strip())<20 or not task or not session or not turn:
        raise ValueError('AUTHOR_ROUTE_REASON_REQUIRED')
    if not paths or any(not isinstance(p,str) or Path(p).is_absolute() or '..' in Path(p).parts or p in {'.',''} for p in paths):
        raise ValueError('AUTHOR_ROUTE_PATHS_REQUIRED')
    if reason in NATIVE_ASSESSMENT_REASONS and assessment is None:
        raise ValueError('CANDIDATE_ASSESSMENT_REQUIRED: supply --assessment-json with native request, capabilities, history, author route and review plan inputs')
    if assessment is not None:
        if reason in NATIVE_ASSESSMENT_REASONS:
            assessment=_native_assessment(assessment,task)
        else:
            if (not isinstance(assessment,dict) or assessment.get('route') not in
                    {'LOCAL_MODEL','CODEX_SUBAGENT','DETERMINISTIC','HOST_AUTHORITY','NO_USEFUL_CANDIDATE'} or
                    not isinstance(assessment.get('reason'),str) or len(assessment['reason'].strip())<20 or
                    not _scoped_paths(assessment.get('candidate_paths'))):
                raise ValueError('CANDIDATE_ASSESSMENT_INVALID')
            assessment={k:assessment[k] for k in ('candidate_paths','route','reason')}
            assessment['execution']='NOT_ESTABLISHED_BY_ASSESSMENT'
    proof=None
    if reason in {'LOCAL_FAILED','LOCAL_CANDIDATE_INTEGRATION'}:
        if not evidence:raise ValueError('AUTHOR_ROUTE_EVIDENCE_REQUIRED')
        raw=Path(evidence).read_bytes();receipt=json.loads(raw)
        # Evidence is the existing task receipt, not a caller's execution boolean.
        if receipt.get('schema') == 'cuhg-local-workspace/v1':
            result=receipt.get('result',{})
            packet=json.loads(Path(evidence).with_name('continuation-intent.json').read_text())
            if receipt.get('model_calls')!=1 or not receipt.get('inference_id'):
                raise ValueError('AUTHOR_ROUTE_LOCAL_EXECUTION_REQUIRED')
            if (receipt.get('repo_root')!=str(repo) or packet.get('task_id')!=receipt.get('task_id')
                    or set(paths)!=set(packet.get('allowed_paths',[]))):
                raise ValueError('AUTHOR_ROUTE_CANDIDATE_SCOPE_MISMATCH')
            if reason=='LOCAL_CANDIDATE_INTEGRATION':
                if result.get('local_success') is not True:
                    raise ValueError('AUTHOR_ROUTE_LOCAL_SUCCESS_REQUIRED')
                if any(sha256((repo/p).read_bytes()).hexdigest()!=result.get('candidate_files_sha256',{}).get(p) for p in paths):
                    raise ValueError('AUTHOR_ROUTE_CANDIDATE_SCOPE_MISMATCH')
"""Temporary PreToolUse overlay: reserved direct reviews only, else installed hook.

The descriptor and all other hooks stay authoritative and unchanged. Installing
this overlay does not install the workspace-job candidate or change hook trust.
"""
from pathlib import Path
import json
import subprocess
import sys

if __package__ in (None, ''):
    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from cuhg.codex_hooks.global_dispatch import state_root, FOLLOWUP_TOOLS, _decision, _tool_name
from cuhg.codex_hooks.child_lifecycle import LifecycleStore
from cuhg.codex_hooks.direct_review_closeout import consume
from cuhg.errors import CuhError


def handle(event, *, root):
    tool = _tool_name(event.get('tool_name', ''))
    if event.get('hook_event_name') != 'PreToolUse' or tool not in FOLLOWUP_TOOLS:
        return None
    input_ = event.get('tool_input', {})
    if not isinstance(input_, dict):
        return None
    session = event.get('session_id', '')
    target = input_.get('target', input_.get('id', input_.get('agent_id')))
    store = LifecycleStore(Path(root) / 'lifecycle')
    binding = store.get_child(session_id=session, child_id=str(target))
    if binding is None or binding.get('continuation_context') is not None:
        return None
    with store._locked(read_only=True) as state:
        if binding['launch_id'] not in state.get('direct_review_closeouts', {}):
            return None
    try:
        consume(root, launch_id=binding['launch_id'], session_id=session,
                child_id=binding['child']['child_id'], client_cwd=event.get('cwd'),
                tool_use_id=event.get('tool_use_id'), message=input_.get('message'))
        return _decision(True, 'RESERVED_DIRECT_REVIEW_CLOSEOUT')
    except (CuhError, ValueError, TypeError, KeyError, OSError):
        return _decision(False, 'DIRECT_REVIEW_CLOSEOUT_NOT_RESERVED: preserve the prior claim and observe the actual outcome.')


def main():
    if sys.argv[1:] == ['--self-check']:
        print('GLOBAL_ROUTING_HOOK_SELF_CHECK_PASS')
        return 0
    raw = sys.stdin.read()
    event = json.loads(raw)
    result = handle(event, root=state_root())
    if result is not None:
        print(json.dumps(result))
        return 0
    descriptor = json.loads((state_root().parents[2]/'runtime/global-execution-policy.json').read_text())
    authority = Path(descriptor['policy_authority']['repo_root'])
    installed = authority/'src/cuhg/codex_hooks/global_dispatch.py'
    if installed.resolve() == Path(__file__).resolve():
        raise ValueError('OVERLAY_MUST_FORWARD_TO_INSTALLED_AUTHORITY')
    forwarded = subprocess.run([sys.executable, '-B', str(installed)], input=raw, text=True)
    return forwarded.returncode


if __name__ == '__main__':
    raise SystemExit(main())
"""Prospective client checks and read-only diagnostics, never lifecycle repair."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Mapping

from cuhg.codex_hooks.child_lifecycle import _identity, _sandbox, pending_launches
from cuhg.errors import CuhError


def observed_parent_sandbox(event: Mapping) -> dict | None:
    """Observe the actual session transcript; tool input cannot override policy."""
    path=event.get('transcript_path')
    if not isinstance(path,str):return None
    session=None;context=None
    try:
        with Path(path).open() as stream:
            for raw in stream:
                try:row=json.loads(raw)
                except ValueError:continue
                payload=row.get('payload',{})
                if not isinstance(payload,dict):continue
                if row.get('type')=='session_meta':session=payload.get('id')
                if row.get('type')=='turn_context':context=payload
        if session!=event.get('session_id') or not context:return None
        if context.get('cwd')!=event.get('cwd',context.get('cwd')):return None
        return _sandbox(context.get('sandbox_policy'))
    except (OSError,ValueError,AttributeError):return None


def launch_issues(record: Mapping, client_cwd: object, *, event: Mapping | None = None) -> list[str]:
    """Check the actual client event cwd, not a prompt or tool-input override."""
    issues = []
    identity = record['identity']
    if not isinstance(client_cwd, str) or not client_cwd or not Path(client_cwd).is_absolute():
        issues.append('CLIENT_WORKTREE_REQUIRED')
    else:
        try:
            if str(Path(client_cwd).resolve(strict=True)) != identity['worktree_root']:
                issues.append('CLIENT_WORKTREE_MISMATCH')
        except (OSError, RuntimeError):
            issues.append('CLIENT_WORKTREE_UNAVAILABLE')
    if _sandbox(record['profile'].get('sandbox_policy')) is None:
        issues.append('REGISTRATION_SANDBOX_REQUIRED')
    if event is not None and event.get('transcript_path'):
        inherited=observed_parent_sandbox(event)
        if inherited is None:
            issues.append('CLIENT_SANDBOX_OBSERVATION_UNAVAILABLE')
        elif inherited!=_sandbox(record['profile'].get('sandbox_policy')):
            issues.append('CLIENT_INHERITED_SANDBOX_MISMATCH')
    try:
        current = _identity(Path(identity['repo_root']), Path(identity['worktree_root']))
        if current != identity:
            issues.append('REGISTERED_IDENTITY_CHANGED')
    except (CuhError, OSError, RuntimeError):
        issues.append('REGISTERED_IDENTITY_UNAVAILABLE')
    return issues


def inspect_launch(root: Path, launch_id: str, client_cwd: str) -> dict:
    """Read the atomic registry snapshot without rewriting it or invoking a model."""
    path = root / 'lifecycle' / 'lifecycle.json'
    from cuhg.codex_hooks.child_lifecycle import LifecycleStore
    from copy import deepcopy
    with LifecycleStore(root/'lifecycle')._locked(read_only=True) as snapshot:
        state=deepcopy(snapshot)
    record = state['launches'].get(launch_id)
    if record is None:
        raise CuhError('LAUNCH_NOT_FOUND', 'No registered launch matches launch_id.', {})
    issues = launch_issues(record, client_cwd)
    pending = pending_launches(state['launches'], record['session_id'], exclude=launch_id)
    if record.get('claim') is None and pending:
        issues.append('LAUNCH_BINDING_PENDING')
    child = record.get('child')
    context = record.get('continuation_context')
    # Direct Host registrations never create a native workspace job. An
    # unclaimed launch needs its first dispatch, not a continuation budget.
    if isinstance(context, dict):
        mode = 'WORKSPACE_JOB'
        action = ('Use native_workspace_job.py plan-continuation --run-dir ' +
                  str(context.get('run_dir')) + '; this inspection reserves nothing.')
    elif record.get('claim') is None and child is None:
        mode = 'DIRECT_UNCLAIMED_LAUNCH'
        action = ('Reuse this launch for its first dispatch from the registered client worktree. '
                  'No workspace_job.json is expected; do not create one or call plan-continuation. '
                  'Resolve prospective_issues before dispatch.')
    else:
        mode = 'DIRECT_LAUNCH_WITHOUT_RESOURCE_CONTEXT'
        action = ('Reconcile the existing claim/child using its actual lifecycle evidence. '
                  'No workspace job is registered; do not invent one or reset its task.')
    return {
        'launch_id': launch_id, 'run_id': record['run_id'], 'task_id': record['task_id'],
        'task_name': record.get('task_name'), 'registered_identity': record['identity'],
        'registered_profile': record['profile'], 'client_cwd_supplied': client_cwd,
        'prospective_issues': issues, 'already_claimed': record.get('claim') is not None,
        'blocking_launches': [{'launch_id': row['launch_id'], 'run_id': row['run_id'],
            'task_id': row['task_id'], 'task_name': row.get('task_name'),
            'tool_use_id': row['claim']['tool_use_id']} for row in pending],
        'bound_child_id': child.get('child_id') if isinstance(child, dict) else None,
        'runtime_observation': child.get('runtime_observation', {}).get('state', 'UNVERIFIED')
            if isinstance(child, dict) else 'UNVERIFIED',
        'continuation_context_present': isinstance(context, dict),
        'execution_mode': mode,
        'workspace_job_expected': isinstance(context, dict),
        'continuation_authorized': False,
        'continuation_action': action,
        'budget_remaining': 'NOT_COMPUTED_BY_INSPECTION',
        'historical_authentication': 'UNCHANGED', 'claim_admitted': False,
        'read_only': True,
    }

"""Fail-open durable metadata spool; no MLflow dependency in the runtime core."""
from __future__ import annotations
from contextlib import contextmanager
from hashlib import sha256
import json
import math
import os
from pathlib import Path
import sys
import time
from uuid import uuid4
from cuhg.observability.purpose import execution_purpose

SAFE_ATTRIBUTES = {'model','effort','provider','route_reason','validation','status','tool','event','artifact_ref','source','cli_version','workspace_policy','error_type','error_code','purpose','method','inference_id','usage_role','usage_event_id'}
SAFE_METRICS = {'input_tokens','output_tokens','cached_input_tokens','total_tokens','duration_ms','ram_peak_bytes','exit_code','prompt_tokens','completion_tokens','attempt','event_count'}


def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()


def spool_root():
    override=os.environ.get('CUHG_TELEMETRY_ROOT')
    if override: return Path(override)
    from cuhg.models.continuous_policy import load_policy
    return Path(load_policy().get('telemetry',{}).get('spool_root', str(Path.home()/'.local/state/cuhg/telemetry')))


def enabled():
    from cuhg.models.continuous_policy import load_policy
    return bool(os.environ.get('CUHG_TELEMETRY_ROOT') or load_policy().get('telemetry',{}).get('enabled'))


def emit(kind: str, *, project='', task='', session='', attempt='', event_id=None, metrics=None, attributes=None, timestamp_ns=None, root=None) -> dict:
    """Idempotency uses caller event identity; never prompt/output bodies or env."""
    try:
        if root is None and not enabled(): return {'status':'DISABLED'}
        root=Path(root) if root else spool_root()
        pending=root/'pending'; pending.mkdir(parents=True,exist_ok=True,mode=0o700)
        root.chmod(0o700)
        attrs={k:v for k,v in (attributes or {}).items() if k in SAFE_ATTRIBUTES and isinstance(v,(str,int,float,bool)) and (not isinstance(v,float) or math.isfinite(v))}
        purpose=execution_purpose(os.environ)
        if purpose=='TEST':attrs['purpose']='TEST'
        else:attrs.setdefault('purpose',purpose)
        numbers={k:v for k,v in (metrics or {}).items() if k in SAFE_METRICS and type(v) in (int,float) and math.isfinite(v)}
        for value in (kind,project,task,session,attempt):
            if not isinstance(value,str) or len(value)>4096: raise ValueError('EVENT_IDENTITY_INVALID')
        identity=event_id or uuid4().hex
        key=sha256(str(identity).encode()).hexdigest()
        event={'schema':'cuhg-observation/v1','event_id':key,'kind':kind,'project':project,'task':task,'session':session,'attempt':attempt,
               'timestamp_ns':timestamp_ns or time.time_ns(),'metrics':numbers,'attributes':attrs}
        path=pending/(key+'.json')
        if (root/'exported'/path.name).exists() or path.exists(): return {'status':'DUPLICATE','event_id':key}
        temp=pending/('.'+uuid4().hex)
        try:
            with temp.open('xb') as stream:
                stream.write(canonical(event));stream.flush();os.fsync(stream.fileno())
            temp.chmod(0o600)
            try: os.link(temp,path)
            except FileExistsError: return {'status':'DUPLICATE','event_id':key}
            fd=os.open(pending,os.O_RDONLY|os.O_DIRECTORY)
            try: os.fsync(fd)
            finally: os.close(fd)
        finally: temp.unlink(missing_ok=True)
        return {'status':'SPOOLED','event_id':key}
    except Exception as error:
        # Only type is printed; exception messages can include private values.
        print('CUHG_TELEMETRY_OBSERVATION_FAILED:'+type(error).__name__,file=sys.stderr)
        return {'status':'OBSERVATION_FAILED','error_type':type(error).__name__}


def observe_hook(event):
    context_ticket=None
    try:
        if enabled() and event.get('hook_event_name') in {'SessionStart','UserPromptSubmit','PreCompact','PostCompact'}:
            from cuhg.models.context_manager import queue_hook
            context_ticket=queue_hook(event,None)
    except (OSError,ValueError,TypeError):
        pass  # Context and observation failures never block the scientific task.
    name=str(event.get('hook_event_name','UNKNOWN'))
    session=str(event.get('session_id',''))
    turn=str(event.get('turn_id') or event.get('tool_use_id') or '')
    identity=(session+':'+turn+':'+name) if turn else None
    observation=emit('codex.'+name,project=str(event.get('cwd','')),task=str(event.get('task_id') or event.get('turn_id') or session),session=session,
                attempt=str(event.get('tool_use_id','')),event_id=identity,
                attributes={'tool':str(event.get('tool_name','')),'source':'GLOBAL_HOOK'})
    if isinstance(context_ticket,dict):
        # Submission may return a completed ticket. Expose observation metadata,
        # never its candidate summary, original request or source content.
        observation={**observation,'context_ticket':{key:context_ticket[key] for key in (
            'ticket_id','queue_state','status','predecessor_id','queue_sequence',
            'enqueued_at','started_at','completed_at','not_before','queue_deadline_at',
            'phase','request_ref','receipt_ref','continue_task') if key in context_ticket}}
    return observation


@contextmanager
def span(name, *, project='', task='', session='', attempt='', event_id=None, attributes=None):
    started=time.monotonic(); record={'metrics':{},'attributes':dict(attributes or {})}
    try:
        yield record
    except BaseException as error:
        record['attributes'].update(status='ERROR',error_type=type(error).__name__);raise
    finally:
        record['metrics']['duration_ms']=(time.monotonic()-started)*1000
        emit(name,project=project,task=task,session=session,attempt=attempt,event_id=event_id,metrics=record['metrics'],attributes=record['attributes'])
"""One owner-authorized closeout for an ended direct reviewer; no launch/rebind.

Reservations are separate from historical launch records. This is a read-only
review conduct contract, not OS sandbox enforcement or candidate admission.
"""
from copy import deepcopy
from hashlib import sha256
import json
from pathlib import Path

from cuhg.codex_hooks.child_lifecycle import LifecycleStore, _runtime_context, _fail
from cuhg.codex_hooks.launch_preflight import launch_issues
from cuhg.models.review_hierarchy import strictly_higher


def _digest(value):
    return sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def _candidate(record, request):
    root = Path(record['identity']['worktree_root'])
    files = request['candidate_files']
    if not isinstance(files, dict) or not files or _digest(files) != request['candidate_digest']:
        raise _fail('REVIEW_CANDIDATE_INVALID', 'Exact candidate file manifest is required.')
    for name, digest in files.items():
        path = root / name
        if Path(name).is_absolute() or not path.resolve().is_relative_to(root):
            raise _fail('REVIEW_CANDIDATE_INVALID', 'Candidate paths must stay inside the registered workspace.')
        if sha256(path.read_bytes()).hexdigest() != digest:
            raise _fail('REVIEW_CANDIDATE_CHANGED', 'Candidate bytes changed before review.')


def _ended(store, record):
    child = record['child']
    observed = child.get('runtime_observation', {})
    turn = observed.get('turn_id')
    if observed.get('state') != 'MATCH' or not turn or not record.get('last_exit_digest'):
        raise _fail('REVIEW_RUNTIME_UNVERIFIED', 'A matched ended reviewer is required.')
    raw = Path(child['transcript_ref']).read_bytes()
    rows = [json.loads(line) for line in raw.splitlines() if line.strip()]
    contexts = [row['payload'] for row in rows if row.get('type') == 'turn_context']
    events = [row['payload'] for row in rows if row.get('type') == 'event_msg'
              and row.get('payload', {}).get('type') in {'task_started', 'task_complete', 'turn_aborted'}]
    if (not contexts or contexts[-1].get('turn_id') != turn or not events
            or events[-1].get('type') != 'task_complete' or events[-1].get('turn_id') != turn):
        raise _fail('REVIEW_NOT_ENDED', 'Latest observed reviewer turn must be complete; running/unknown is refused.')
    runtime = _runtime_context(record, {'turn_id': turn})
    if runtime['state'] != 'MATCH':
        raise _fail('REVIEW_RUNTIME_UNVERIFIED', 'Raw runtime differs from the registered reviewer.')
    store._revalidate_frozen_validator(record)
    usages = [row['payload']['info']['total_token_usage'] for row in rows
              if row.get('type') == 'event_msg' and row.get('payload', {}).get('type') == 'token_count'
              and isinstance(row['payload'].get('info'), dict)
              and isinstance(row['payload']['info'].get('total_token_usage'), dict)]
    if not usages or type(usages[-1].get('total_tokens')) is not int or usages[-1]['total_tokens'] < 0:
        raise _fail('REVIEW_USAGE_UNKNOWN', 'Observed cumulative reviewer usage is required.')
    return {'transcript_sha256': sha256(raw).hexdigest(), 'turn_id': turn,
            'cumulative_usage': usages[-1], 'runtime_observation': runtime}


def _validate(store, record, request, cwd):
    for key in ('launch_id', 'session_id', 'run_id', 'task_id'):
        if request[key] != record[key]:
            raise _fail('REVIEW_IDENTITY_MISMATCH', 'Closeout must retain the original task and launch.')
    if (record.get('continuation_context') is not None or not record.get('claim')
            or request['child_id'] != record['child']['child_id']):
        raise _fail('REVIEW_IDENTITY_MISMATCH', 'Only the existing direct reviewer is eligible.')
    if launch_issues(record, cwd):
        raise _fail('REVIEW_IDENTITY_MISMATCH', 'Client and registered source must still match.')
    profile = record['profile']
    if profile.get('profile_id') not in {'cuhg_gpt6_astra_reviewer', 'cuhg_gpt6_sol_reviewer'}:
        raise _fail('REVIEW_PROFILE_REQUIRED', 'This route is for existing named reviewers only.')
    if request.get('scope') != 'READ_ONLY_REVIEW_CLOSEOUT' or request.get('max_consumptions') != 1:
        raise _fail('REVIEW_SCOPE_INVALID', 'Only one read-only closeout invocation is permitted.')
    approval = request['owner_approval']
    # Host supplies the explicit owner decision, never a child self-authorization.
    for key in ('launch_id', 'child_id', 'task_id', 'candidate_digest'):
        if approval.get(key) != request[key]:
            raise _fail('REVIEW_APPROVAL_MISMATCH', 'Owner approval must name this exact closeout.')
    if approval.get('authorized') is not True or not approval.get('source'):
        raise _fail('REVIEW_APPROVAL_REQUIRED', 'Explicit owner approval is required.')
    author = request['author']
    ordinary = strictly_higher(author['model'], author['effort'], profile['model'], profile['effort'], author_kind='HOST_CODEX')
    exception = (approval.get('exception') == 'SAME_TASK_ASTRA_HIGH_TO_ASTRA_XHIGH'
                 and (author['model'], author['effort'], profile['model'], profile['effort'])
                 == ('gpt-6-astra', 'high', 'gpt-6-astra', 'xhigh'))
    if not ordinary and not exception:
        raise _fail('REVIEW_HIERARCHY_UNSATISFIED', 'No applicable exact-candidate owner exception.')
    if not isinstance(request.get('prompt_sha256'), str) or len(request['prompt_sha256']) != 64:
        raise _fail('REVIEW_PROMPT_REQUIRED', 'Freeze the exact followup prompt.')
    _candidate(record, request)
    return _ended(store, record)


def reserve(root, *, request, client_cwd, owner_authorized=False, check=False):
    if not owner_authorized:
        raise _fail('REVIEW_APPROVAL_REQUIRED', 'Host owner authorization is required.')
    store = LifecycleStore(Path(root) / 'lifecycle')
    with store._locked(read_only=check) as state:
        record = state['launches'][request['launch_id']]
        observed = _validate(store, record, request, client_cwd)
        prior = state.get('direct_review_closeouts', {}).get(record['launch_id'])
        if prior:
            if prior['request'] != request:
                raise _fail('REVIEW_CLOSEOUT_ALREADY_RESERVED', 'Do not replace or reset this task closeout.')
            return deepcopy(prior)
        receipt = {'status': 'CHECK_ONLY' if check else 'RESERVED', 'request': deepcopy(request),
                   'baseline': observed, 'launch_sha256': _digest(record), 'consumption': None,
                   'dispatch_refunded': False, 'claim_admitted': False,
                   'os_read_only_enforced': False}
        if not check:
            state.setdefault('direct_review_closeouts', {})[record['launch_id']] = receipt
        return deepcopy(receipt)


def consume_continuation(run_dir: Path, *, selection_id: str, thread_id: str,
                         model: str, effort: str, tool_use_id: str) -> dict:
    """The supported pre-tool boundary consumes the existing workspace reservation."""
    if not tool_use_id:
        raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'Actual tool-use identity is required.')
    run = Path(run_dir).resolve()
    with _locked(run):
        job = _job(run)
        reservations = [job.get(key) for key in ('continuation_reservation', 'review_continuation_reservation')]
        reservation = next((item for item in reservations if isinstance(item, dict) and
            item.get('selection_id') == selection_id and item.get('thread_id') == thread_id and
            item.get('settings') == [model, effort]), None)
        if reservation is None:
            raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'No formal continuation binds this child.')
        if reservation.get('kind') == 'PRE_CANDIDATE_AUTHOR':
            _check_pre_candidate_reservation(run, job, reservation)
            if reservation.get('tool_use_id'):
                raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'Pre-candidate launch already consumed; observe its outcome before any retry.')
            _pre_candidate_resources(job)
            reservation['tool_use_id'] = tool_use_id
            job['continuations'] += 1
            _save_job(run, job)
            return dict(reservation)
        if reservation.get('tool_use_id') == tool_use_id: return dict(reservation)
        if reservation.get('tool_use_id') or job['continuations'] >= MAX_CONTINUATIONS:
            raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'Continuation is already consumed or exhausted.')
        _check_usage_budget(job['usage_events'], **_budget_guard_options(job, require_measured=True))
        _spending_decision(job)
        if len(job['usage_events']) >= 4:
            raise fail('WORKSPACE_BUDGET_EXHAUSTED', 'No resource remains for another generation.')
        if not job['candidates'] or reservation['candidate_digest'] != job['candidates'][-1]['candidate_digest']:
            raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'Reservation is stale.')
        reservation['tool_use_id'] = tool_use_id
        _save_job(run, job)
        return dict(reservation)


def plan_continuation(run_dir: Path) -> dict:
    run = Path(run_dir).resolve(); job = _job(run)
    decision = _spending_decision(job)
    if not job['candidates'] or not job['reviews'] or job['reviews'][-1]['candidate_digest'] != job['candidates'][-1]['candidate_digest']:
        raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'A review of the current candidate is required.')
    if not job['reviews'][-1]['findings'] or job['continuations'] >= MAX_CONTINUATIONS:
        raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'A nonempty structured review finding is required for bounded author revision.')
    if len(job['usage_events']) >= 4:
        raise fail('WORKSPACE_BUDGET_EXHAUSTED', 'Continuation budget is exhausted by observed turns or wall time.')
    _check_usage_budget(job['usage_events'], **_budget_guard_options(job, require_measured=True))
    selection_id = job['candidates'][-1]['selection_id']
    ledger = _state(run, _packet(run)); author = next((item for item in ledger['dispatches'] if item.get('selection_id') == selection_id), None)
    if not author or author.get('status') not in {'CANDIDATE_RETURNED','WRITTEN_ARTIFACT_READY'}:
        raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'Author reservation is not attributable and closed.')
    reservation = {'selection_id':selection_id, 'thread_id':author['observation']['thread_id'],
                   'settings':[author['model'],author['model_reasoning_effort'],],
                   'candidate_digest':job['candidates'][-1]['candidate_digest'], 'review_digest':job['reviews'][-1]['report_digest']}
    with _locked(run):
        latest = _job(run)
        if isinstance(latest.get('continuation_reservation'), dict) and latest['continuation_reservation'].get('tool_use_id'):
            raise fail('WORKSPACE_CONTINUATION_UNAVAILABLE', 'The prior continuation is still in flight.')
        latest['continuation_reservation'] = reservation; _save_job(run, latest)
    return {'action': 'CONTINUE_EXISTING_THREAD', 'selection_id': selection_id, 'thread_id':reservation['thread_id'],
            'continuations_remaining': MAX_CONTINUATIONS - job['continuations'], 'claim_admitted': False, 'budget_decision': decision}


def finalize_job(run_dir: Path, *, runner: Callable | None = None, host_validation: dict | None = None) -> dict:
    """Run frozen Host validators when supplied; this never installs or admits a claim."""
    run = Path(run_dir).resolve(); job = _job(run)
    if not job['candidates'] or not job['reviews'] or job['reviews'][-1].get('status') != 'REVIEW_READY' or \
            job['reviews'][-1]['candidate_digest'] != job['candidates'][-1]['candidate_digest']:
        return {'status': 'HOST_VALIDATION_REQUIRED', 'task_complete': False, 'claim_admitted': False}
    if runner is None or not job['validators']:
        return {'status': 'HOST_VALIDATION_REQUIRED', 'task_complete': False, 'claim_admitted': False}
    if candidate_digest(Path(job['workspace']), job['allowed_paths']) != job['candidates'][-1]['candidate_digest']:
        return {'status':'WORKSPACE_CANDIDATE_CHANGED','task_complete':False,'claim_admitted':False}
    source_identity = _frozen_nonallowed_source_identity(job)
    if source_identity is None:
        return {'status':'WORKSPACE_SOURCE_IDENTITY_CHANGED','task_complete':False,'claim_admitted':False}
    checks = []
    if host_validation is None:
        workspace = Path(job['workspace'])
        for item in job['validators']:
            if not isinstance(item, dict) or not isinstance(item.get('argv'), list) or not isinstance(item.get('timeout_seconds'), int):
                raise fail('WORKSPACE_VALIDATOR_INVALID', 'Frozen validators require argv and timeout_seconds.')
            result = runner(item['argv'], workspace, item['timeout_seconds'], run / 'host-validation' / str(item.get('id','validator')))
            checks.append({'id': item.get('id'), 'exit_code': result.get('exit_code'), 'stdout_ref': result.get('stdout_ref'), 'stderr_ref': result.get('stderr_ref')})
        if any(check['exit_code'] != 0 for check in checks):
            return {'status': 'HOST_VALIDATION_REJECTED', 'task_complete': False, 'claim_admitted': False, 'checks': checks}
    else:
        return {'status':'HOST_VALIDATION_REQUIRED','task_complete':False,'claim_admitted':False}
    _check_lean_root_correction(job)
    if candidate_digest(Path(job['workspace']), job['allowed_paths']) != job['candidates'][-1]['candidate_digest']:
        return {'status':'WORKSPACE_CANDIDATE_CHANGED','task_complete':False,'claim_admitted':False}
    if _frozen_nonallowed_source_identity(job) != source_identity:
        return {'status':'WORKSPACE_SOURCE_IDENTITY_CHANGED','task_complete':False,'claim_admitted':False}
    result = {'status': 'WORKSPACE_ARTIFACT_VALIDATED', 'task_complete': True, 'claim_admitted': False,
              'task_id': job['task_id'], 'candidate_digest': job['candidates'][-1]['candidate_digest'],
              'nonallowed_source_identity': source_identity,
              'claim_ceiling': 'STRUCTURAL_OR_SEMANTIC_ONLY_EXTERNAL_ADMISSION_REQUIRED', 'checks': checks}
    job['host_validations'].append(result); job['status'] = result['status']; _save_job(run, job)
    return result


def enroll_comparable_work(run_dir: Path, enrollment: dict) -> dict:
    """Host-only writer for pre-execution comparable-work authority.

    The caller selects neither a root nor an authority map here: ``run_dir`` is
    opened by Host orchestration and this function validates it against the
    already durable job before it appends an immutable record.
    """
